import { expect, test } from 'bun:test'
import { createSession } from '../src/auth'
import { handle } from '../src/api/routes'

const lines = [{ sku: 'mug', priceCents: 1200, qty: 2 }, { sku: 'tee', priceCents: 2500, qty: 1 }]

function order(body: unknown) {
  const token = createSession('u1', 'customer')
  return handle(new Request('http://x/v1/orders', {
    method: 'POST',
    headers: { authorization: token },
    body: JSON.stringify(body),
  }))
}

test('client-supplied discountPercent is ignored without a code', async () => {
  const res = await order({ cart: { lines, discountPercent: 150 } })
  expect(res.status).toBe(201)
  expect((await res.json()).totalCents).toBe(4900)
})

test('a valid code still applies', async () => {
  const res = await order({ cart: { lines, discountPercent: 0 }, code: 'WELCOME10' })
  expect((await res.json()).totalCents).toBe(4410)
})

